using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts dynamic values
        // like DateTime.UtcNow — seed data must be constant/deterministic.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change: The Cosmos provider now uses
            // "$type" instead of "Discriminator" by default.
            // To maintain compatibility with existing documents that use
            // "Discriminator", explicitly configure it:
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// --- Cosmos queries: EF Core 9 removed synchronous I/O for Cosmos ---

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous Cosmos DB queries are no longer
    // supported. Use async methods instead (ToListAsync, FirstOrDefaultAsync, etc.)
    async Task<List<Product>> GetProductsAsync(CosmosDbContext db)
    {
        return await db.Products
            .Where(p => p.Category == "Electronics")
            .ToListAsync();
    }
}

